//! Verifies a real proof of the weather circuit (generated by
//! `circuits/weather_threshold_noir/scripts/prove-fixture.sh`) in the Soroban host.
use noir_verifier::{Error, NoirVerifier, NoirVerifierClient};
use soroban_sdk::{Bytes, Env};

const VK: &[u8] = include_bytes!("../../../circuits/weather_threshold_noir/artifacts/vk");
const PROOF: &[u8] = include_bytes!("../../../circuits/weather_threshold_noir/artifacts/proof");
const PUBLIC_INPUTS: &[u8] = include_bytes!("../../../circuits/weather_threshold_noir/artifacts/public_inputs");

fn setup(env: &Env) -> NoirVerifierClient<'_> {
    let id = env.register(NoirVerifier, (Bytes::from_slice(env, VK),));
    NoirVerifierClient::new(env, &id)
}

#[test]
fn verifies_the_fixture_proof() {
    let env = Env::default();
    env.cost_estimate().budget().reset_unlimited();
    let client = setup(&env);
    client.verify_proof(&Bytes::from_slice(&env, PUBLIC_INPUTS), &Bytes::from_slice(&env, PROOF));
    let cpu = env.cost_estimate().budget().cpu_instruction_cost();
    std::println!("verify_proof CPU instructions: {cpu}");
    assert!(cpu < 400_000_000, "over the per-transaction limit: {cpu}");
}

#[test]
fn rejects_changed_public_inputs() {
    let env = Env::default();
    env.cost_estimate().budget().reset_unlimited();
    let client = setup(&env);
    // Bump the damage percentage (last 32-byte input) from 85 to 86.
    let mut inputs = PUBLIC_INPUTS.to_vec();
    *inputs.last_mut().unwrap() += 1;
    let res = client.try_verify_proof(&Bytes::from_slice(&env, &inputs), &Bytes::from_slice(&env, PROOF));
    assert_eq!(res, Err(Ok(Error::VerificationFailed)));
}

#[test]
fn rejects_a_truncated_proof() {
    let env = Env::default();
    let client = setup(&env);
    let res = client.try_verify_proof(&Bytes::from_slice(&env, PUBLIC_INPUTS), &Bytes::from_slice(&env, &PROOF[..PROOF.len() - 32]));
    assert_eq!(res, Err(Ok(Error::ProofParseError)));
}
